export function practiceCopy(base,language,place,duration=60,pattern='4-6'){
 let t={...base,...optionCopy[language],guides:{...base.guides}};
 if(duration===60){const local=shortCopy[language],cues=[...local.cues];if(place==='city')cues[2]=local.light;t.guides.journey={...base.guides.journey,cues,about:local.about};t.journeyHint=local.hint;}
 if(pattern==='5-5'){
  const replace=text=>text.replaceAll('Vier Sekunden ein, sechs Sekunden aus.','Fünf Sekunden ein, fünf Sekunden aus.').replaceAll('Four seconds in, six seconds out.','Five seconds in, five seconds out.').replaceAll('Quatre secondes pour inspirer, six pour expirer.','Cinq secondes pour inspirer, cinq pour expirer.').replaceAll('Vier Sekunden ein und sechs Sekunden aus','Fünf Sekunden ein und fünf Sekunden aus').replaceAll('Four seconds in and six seconds out','Five seconds in and five seconds out').replaceAll('Quatre secondes pour inspirer et six pour expirer','Cinq secondes pour inspirer et cinq pour expirer').replaceAll('vier Sekunden heller und sechs Sekunden dunkler','fünf Sekunden heller und fünf Sekunden dunkler').replaceAll('four seconds and dims for six','five seconds and dims for five').replaceAll('pendant quatre secondes, puis s’atténue pendant six secondes','pendant cinq secondes, puis s’atténue pendant cinq secondes');
  t.guides=Object.fromEntries(Object.entries(t.guides).map(([key,g])=>[key,{...g,about:replace(g.about),cues:g.cues.map(replace)}]));
  t.inhaleDuration=({de:'5 Sekunden',en:'5 seconds',fr:'5 secondes'})[language];t.exhaleDuration=t.inhaleDuration;
 }
 return t;
}
